def encode(message):
    vowels = {'a', 'e', 'i', 'o', 'u'}
    result = []
    for char in message:
        if char.isalpha():
            if char in vowels:
                # Replace with the letter 2 places ahead
                vowel_index = vowels.index(char)
                new_vowel = vowels[(vowel_index + 2) % 5]
                result.append(new_vowel)
            else:
                # Swap case
                result.append(char.swapcase())
        else:
            result.append(char)
    return ''.join(result)

