def fix_spaces(text):
    """
    Given a string text, replace all spaces in it with underscores, 
    and if a string has more than 2 consecutive spaces, 
    then replace all consecutive spaces with - 
    """
    result = []
    prev_spaces = 0
    for char in text:
        if char == ' ':
            if prev_spaces == 0:
                prev_spaces = 1
            else:
                prev_spaces += 1
            if prev_spaces > 2:
                result.append('-')
                prev_spaces = 1
        else:
            result.append(char)
            prev_spaces = 0
    return ''.join(result)

