def Strongest_Extension(class_name, extensions):
    def calculate_strength(extension):
        cap = sum(1 for c in extension if c.isupper())
        sm = sum(1 for c in extension if c.islower())
        return (cap - sm, extension)

    # Sort extensions by strength (ascending), then by their original order
    sorted_extensions = sorted(extensions, key=lambda x: (calculate_strength(x), extensions.index(x)))
    strongest_extension = sorted_extensions[0]
    return f"{class_name}.{strongest_extension}"

